do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero) values ($q$UBER$q$,$q$Uber Technologies$q$,$q$consumer$q$,$q$large$q$,true,true),($q$AAPL$q$,$q$Apple$q$,$q$consumer$q$,$q$large$q$,true,false),($q$META$q$,$q$Meta Platforms$q$,$q$consumer$q$,$q$large$q$,true,false),($q$MSFT$q$,$q$Microsoft$q$,$q$business$q$,$q$large$q$,true,false),($q$PLTR$q$,$q$Palantir Technologies$q$,$q$business$q$,$q$large$q$,true,false),($q$NVDA$q$,$q$NVIDIA$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$TSM$q$,$q$Taiwan Semiconductor Manufacturing$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$AMD$q$,$q$Advanced Micro Devices$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$DASH$q$,$q$DoorDash$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$NET$q$,$q$Cloudflare$q$,$q$business$q$,$q$mid$q$,true,false),($q$CRWV$q$,$q$CoreWeave$q$,$q$infrastructure$q$,$q$mid$q$,true,true),($q$CBRS$q$,$q$Cerebras Systems$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$NBIS$q$,$q$Nebius Group$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$LYFT$q$,$q$Lyft$q$,$q$consumer$q$,$q$small$q$,true,true),($q$APLD$q$,$q$Applied Digital$q$,$q$infrastructure$q$,$q$small$q$,true,false),($q$AMZN$q$,$q$Amazon$q$,$q$consumer$q$,$q$large$q$,true,false),($q$GOOGL$q$,$q$Alphabet$q$,$q$consumer$q$,$q$large$q$,true,false),($q$TSLA$q$,$q$Tesla$q$,$q$consumer$q$,$q$large$q$,true,false),($q$ORCL$q$,$q$Oracle$q$,$q$business$q$,$q$large$q$,true,false),($q$INTC$q$,$q$Intel$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$LCID$q$,$q$Lucid$q$,$q$consumer$q$,$q$small$q$,true,false),($q$LIME$q$,$q$Lime$q$,$q$consumer$q$,$q$small$q$,true,false),($q$CART$q$,$q$Instacart$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$GRAB$q$,$q$Grab$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$AUR$q$,$q$Aurora$q$,$q$business$q$,$q$small$q$,true,false) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero;
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Al Bawani$q$,$q$private_company$q$),($q$Aston Martin$q$,$q$public_company$q$),($q$Government of Saudi Arabia$q$,$q$institution$q$),($q$Nuro$q$,$q$private_company$q$),($q$PIF$q$,$q$institution$q$),($q$Rivian$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$EV manufacturers with which we compete include Tesla, Rivian, an increasing number of U.S.-based and international entrants and traditional automotive manufacturers, many of which have begun, or announced plans to begin, selling their own EVs in the near-term.$q$),(2,$q$For example, in July 2025, we entered into an integration agreement with Nuro to install autonomous driving software in Lucid Gravity vehicles, in conjunction with our agreement with Uber, to enable Uber and its designated fleet operators to operate the vehicles with Level 4 autonomy.$q$),(3,$q$In 2025, Lucid formed a partnership with Uber Technologies, Inc. (“Uber”) and Nuro, Inc. (“Nuro”) to launch a next-generation autonomous robotaxi leveraging Lucid Gravity’s advanced technology platform, redundant electrical and controls architectures, and long range, which together make it an ideal fit for use in a scalable robotaxi offering.$q$),(4,$q$In August 2023, Lucid LLC entered into the EV Purchase Agreement with the Government of Saudi Arabia, a related party of the PIF, which is an affiliate of Ayar, as represented by the Ministry of Finance.$q$),(5,$q$In July 2025, the Company entered into the 2025 Subscription Agreement with SMB, a subsidiary of Uber, under which the Company agreed to issue and SMB agreed to purchase, in a private placement, the Company’s common stock equal to (i) $
300.0
 million in cash divided by (ii) an amount equal to the arithmetic average of the daily volume-weighted average price of the common stock over a period of 
30
 consecutive trading days ending on, and including, July 15, 2025.$q$),(6,$q$In July 2025, we entered into the Vehicle Production Agreement (“VPA”) with Uber under which Uber and its designated fleet operators have agreed to purchase a minimum commitment of 20,000 Lucid Gravity Plus vehicles over a six-year period following the start of production.$q$),(7,$q$In June 2023, we entered into an agreement (the “Implementation Agreement”) with Aston Martin Lagonda Global Holdings plc (together with its subsidiaries, “Aston Martin”), under which we and Aston Martin have established a long-term strategic technology and supply arrangement.$q$),(8,$q$In June 2023, we entered into the Implementation Agreement with Aston Martin under which we and Aston Martin have established a long-term strategic technology arrangement.$q$),(9,$q$Increasing use of such products and services in our vehicles, including with our partnerships with Nuro and Uber for AV capabilities, heightens the risk and potential impacts of a cybersecurity breach of our or our third-party partners’ systems.$q$),(10,$q$Lucid LLC entered into agreements with Al Bawani Company Limited (“Al Bawani”), an affiliate of the PIF, which is an affiliate of Ayar, for certain design and construction services in connection with the development of AMP-2.$q$),(11,$q$On July 16, 2025, the Company entered into the VPA with Uber and the 2025 Subscription Agreement with SMB, a subsidiary of Uber.$q$),(12,$q$On November 6, 2023, in connection with the commencement of the Strategic Technology Arrangement with Aston Martin, we received 28,352,273 ordinary shares of Aston Martin.$q$),(13,$q$On November 6, 2023, the Company received 
28,352,273
 ordinary shares of Aston Martin with an initial fair value of $
73.2
 million.$q$),(14,$q$Pursuant to the terms of the EV Purchase Agreement, the Government of Saudi Arabia and its entities and corporate subsidiaries and other beneficiaries (collectively, the “Purchaser”) may purchase up to 100,000 vehicles, with a minimum purchase quantity of 50,000 vehicles and an option to purchase up to an additional 50,000 vehicles during a ten-year period.$q$),(15,$q$The PIF and Ayar beneficially own a significant equity interest in us and may take actions that conflict with other stockholders’ interests.$q$),(16,$q$Under the VPA, Uber and its designated fleet operators have agreed to purchase a minimum commitment of 20,000 (the “Minimum Quantity Guarantee”) Lucid Gravity vehicles that have been modified to include certain autonomous driving hardware and other features (the “Lucid Gravity Plus vehicles”).$q$),(17,$q$We have an agreement with the Government of Saudi Arabia, as represented by the Ministry of Finance, under which the Government of Saudi Arabia and its entities and corporate subsidiaries and other beneficiaries undertook to purchase up to 100,000 vehicles, with a minimum purchase quantity of 50,000 vehicles and an option to purchase up to an additional 50,000 vehicles over a ten-year period.$q$),(18,$q$We hold equity securities of Aston Martin.$q$),(19,$q$our ability to realize the anticipated benefits of our partnerships with Aston Martin, Uber, Nuro, and NVIDIA;$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$partners$q$,$q$LCID$q$,$q$Aston Martin$q$,$q${7,8,12}$q$::int[],$q${business,risk_factors,mdna}$q$::text[],null,null,null,null),(2,$q$partners$q$,$q$LCID$q$,$q$Uber$q$,$q${3,2,9}$q$::int[],$q${business,risk_factors,risk_factors}$q$::text[],null,null,null,null),(3,$q$partners$q$,$q$LCID$q$,$q$Nuro$q$,$q${3,2,9}$q$::int[],$q${business,risk_factors,risk_factors}$q$::text[],null,null,null,null),(4,$q$partners$q$,$q$LCID$q$,$q$NVIDIA$q$,$q${19}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(5,$q$sells_to$q$,$q$LCID$q$,$q$Government of Saudi Arabia$q$,$q${17,14,4}$q$::int[],$q${business,risk_factors,notes}$q$::text[],null,null,null,null),(6,$q$competes$q$,$q$LCID$q$,$q$Tesla$q$,$q${1}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(7,$q$competes$q$,$q$LCID$q$,$q$Rivian$q$,$q${1}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(8,$q$sells_to$q$,$q$LCID$q$,$q$Uber$q$,$q${6,16}$q$::int[],$q${risk_factors,notes}$q$::text[],null,null,null,null),(9,$q$invests$q$,$q$PIF$q$,$q$LCID$q$,$q${15}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(10,$q$invests$q$,$q$LCID$q$,$q$Aston Martin$q$,$q${12,18,13}$q$::int[],$q${mdna,notes,notes}$q$::text[],null,null,null,null),(11,$q$invests$q$,$q$Uber$q$,$q$LCID$q$,$q${5,11}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(12,$q$supplies$q$,$q$Al Bawani$q$,$q$LCID$q$,$q${10}$q$::int[],$q${notes}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Uber$q$ then ticker=$q$UBER$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$Tesla$q$ then ticker=$q$TSLA$q$ when $q$LCID$q$ then ticker=$q$LCID$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$LCID 10-K M6 (staged)$q$,'claude-sonnet-5-5 via Claude Code session',1.1698,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1811210/000162828026011053/lcid-20251231.htm$q$,r.sec[k],t,true,$q$2026-02-24$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
